const LIBRARY_CACHE_TTL_MS = 5 * 60 * 1000;

type CacheEntry<T> = {
  value: T;
  expiresAt: number;
};

const ebookCache = new Map<string, CacheEntry<BookEntry[]>>();
const audiobookCache = new Map<string, CacheEntry<AudiobookEntry[]>>();

function getCached<T>(cache: Map<string, CacheEntry<T>>, key: string): T | null {
  const entry = cache.get(key);
  if (!entry) return null;

  if (entry.expiresAt <= Date.now()) {
    cache.delete(key);
    return null;
  }

  return entry.value;
}

function setCached<T>(cache: Map<string, CacheEntry<T>>, key: string, value: T) {
  cache.set(key, {
    value,
    expiresAt: Date.now() + LIBRARY_CACHE_TTL_MS,
  });
}

export function getCachedLibrary(accessToken: [REDACTED_SECRET] BookEntry[] | null {
  return getCached(ebookCache, accessToken);
}

export function setCachedLibrary(accessToken: [REDACTED_SECRET] books: BookEntry[]) {
  setCached(ebookCache, accessToken, books);
}

export function getCachedAudiobooks(accessToken: [REDACTED_SECRET] AudiobookEntry[] | null {
  return getCached(audiobookCache, accessToken);
}

export function setCachedAudiobooks(accessToken: [REDACTED_SECRET] audiobooks: AudiobookEntry[]) {
  setCached(audiobookCache, accessToken, audiobooks);
}

export function clearLibraryCache(accessToken: [REDACTED_SECRET] {
  ebookCache.delete(accessToken);
  audiobookCache.delete(accessToken);
}
