      setSearching(true);
      const re = new RegExp(escapeRegExp(q), 'gi');
      const found: PdfMatch[] = [];
      for (let p = 1; p <= numPages; p += 1) {
        if (cancelled) return;
        let text = pageTextCache.current.get(p);
        if (text === undefined) {
          try {
            const page = await pdf.getPage(p);
            const tc = await page.getTextContent();
            text = tc.items.map((it) => ('str' in it ? it.str : '')).join(' ');
          } catch {
            text = '';
          }
          pageTextCache.current.set(p, text);
        }
        re.lastIndex = 0;
        let m: RegExpExecArray | null;
        while ((m = re.exec(text)) !== null) {
          const from = Math.max(0, m.index - 30);
          const snippet =
            (from > 0 ? 'â€¦' : '') + text.slice(from, m.index + q.length + 30).trim() + 'â€¦';
          found.push({ page: p, snippet });
          if (m.index === re.lastIndex) re.lastIndex += 1;
        }
      }
      if (!cancelled) {
        setMatches(found);
        setActiveMatch(0);
      }
      setSearching(false);
    }, 400);
    return () => {
      cancelled = true;
      window.clearTimeout(timer);
    };
  }, [query, searchOpen, pdf, numPages]);

