            >
              <div className="mb-4 flex items-center justify-between gap-4 text-sm text-slate-300">
                <span>Page {pageNumber}</span>
                <span>{pageNumber === currentPage ? 'Visible' : ''}</span>
              </div>
              <div className="overflow-hidden rounded-3xl bg-black">
